/* Bo tròn 8px giao diện Teeinblue */
.teeinblue-enabled button.tee-btn,
.teeinblue-enabled div.tee-radio,
.teeinblue-enabled .tee-field__select,
.teeinblue-enabled .tee-form-input,
.teeinblue-enabled .tee-clipart,
.teeinblue-enabled .tee-photo-placeholder,
.teeinblue-enabled .tee-photo-action .tee-btn,
.teeinblue-enabled .tee__paragraph,
.teeinblue-enabled .tee-timepicker__input {
  border-radius: 8px !important;
}

.teeinblue-enabled .tee-quantity-minus {
  border-top-left-radius: 8px;
  border-bottom-left-radius: 8px;
}

.teeinblue-enabled .tee-quantity-plus {
  border-top-right-radius: 8px;
  border-bottom-right-radius: 8px;
}

.tee-slider .tee-slide,
.tee-mockup-item .tee-mockup-image,
.tee-mockup-item .tee-printarea-wrapper--image > img {
  border-radius: 8px;
}

/* Hỗ trợ hiển thị RTL cho Teeinblue */
@media only screen and (min-width: 992px) {
  .tee-dialog-image-cropper.vm--modal {
    left: -50% !important;
    transform: translateX(50%) !important;
  }
}

@media only screen and (max-width: 990px) {
  .teeinblue-enabled .product {
    overflow: hidden;
  }
}

/* Image Cropper Classic Style */
.tee-dialog-image-cropper .cropper-view-box {
  outline: 2px solid #fff !important;
  outline-color: rgba(255, 255, 255, 0.75) !important;
}

.tee-dialog-image-cropper .cropper-line {
  background-color: transparent !important;
}

.tee-dialog-image-cropper .cropper-point {
  width: 10px !important;
  height: 10px !important;
  background-color: #39f !important;
}

/* Fix preview popup overlap */
.vm--container.tee-preview-popup,
.vm--container.tee-dialog-preview {
  z-index: 99999999 !important;
}

.teeinblue-enabled .shopify-section-header-sticky {
  z-index: 100 !important;
}

/* Fix scrollable in iOS browsers */
html.tee-overflow-hidden,
body.tee-overflow-hidden {
  position: static !important;
  overflow: auto !important;
  -webkit-overflow-scrolling: touch;
}

/* Loading shimmer placeholder */
#tib-loading-placeholder {
  width: 100%;
  padding: 24px;
  background: #f7f7f7;
  border-radius: 8px;
  margin-bottom: 16px;
  text-align: center;
  color: #666;
  font-weight: 500;
  animation: tibPulse 1.5s infinite;
}

@keyframes tibPulse {
  0% { opacity: 0.6; }
  50% { opacity: 1; }
  100% { opacity: 0.6; }
}

/* Style dành cho Theme nền đen (Dark Theme) */
.teeinblue-enabled .tee-price--current {
  color: #fff !important;
  font-weight: 700;
}

.teeinblue-enabled .tee-radio {
  border: 1px solid rgba(255, 255, 255, 0.2) !important;
  border-radius: 4px !important;
  background: none !important;
}

.teeinblue-enabled .tee-radio:hover {
  box-shadow: 0 1px 3px rgba(255, 255, 255, 0.4);
  border-color: rgba(255, 255, 255, 0.4) !important;
}

.teeinblue-enabled .tee-radio.active {
  box-shadow: 0 0 0 2px rgba(255, 255, 255, 0.6);
  border-color: rgba(255, 255, 255, 0.6) !important;
}

.teeinblue-enabled .tee-radio .tee-radio-label {
  background-color: #000;
  color: #fff !important;
  border-radius: 4px !important;
}

.teeinblue-enabled .tee-radio.tee-radio--unavailable:before {
  content: "";
  position: absolute;
  background-color: rgba(255, 255, 255, 0.3);
  width: calc(100% + 8px);
  height: 2px;
  transform: rotate(30deg);
  bottom: calc(50% - 1px);
  left: -4px;
}

@media only screen and (max-width: 768px) {
  .teeinblue-enabled .tee-form-actions:not(.tee-form-actions--no-sticky) {
    background-color: #000 !important;
  }
}

/* Clipart 4 cột 1 hàng trên Mobile */
@media only screen and (max-width: 767px) {
  .tee-field__input .tee-clipart-row {
    display: grid !important;
    grid-template-columns: repeat(4, minmax(65px, 1fr)) !important;
    gap: 8px !important;
    justify-content: start;
  }
}

/* Bố cục Upload Photo nhiều cột */
.tee-form-wrapper .tee-form-inputs {
  display: flex !important;
  flex-wrap: wrap !important;
}

.tee-form-wrapper .tee-form-inputs > .tee-field--photo {
  flex: 0 0 50%;
  max-width: calc(50% - 10px);
  padding: 0 5px;
  margin-bottom: 12px;
}

@media only screen and (min-width: 1025px) {
  .tee-form-wrapper .tee-form-inputs > .tee-field--photo {
    flex: 0 0 33.33%;
    max-width: calc(33.33% - 10px);
  }
}

@media only screen and (max-width: 749px) {
  .tee-form-wrapper .tee-form-inputs > .tee-field--photo {
    flex: 0 0 100%;
    max-width: 100%;
  }
}

/* Badge Save Amount trên Price */
.tee-block.tee-product-price {
  position: relative;
  margin-top: 30px !important;
}

.tee-block.tee-product-price .tee-price--saving {
  position: absolute;
  top: -24px;
  left: 0;
  background: #e53e3e;
  color: #fff;
  font-size: 12px;
  font-weight: 700;
  padding: 2px 8px;
  border-radius: 4px;
  text-transform: uppercase;
}
